'use strict';
const assert=require('node:assert/strict'),E=require('../src/engine.js');let passed=0;
function test(name,fn){try{fn();passed++;console.log('PASS',name);}catch(e){console.error('FAIL',name,e);process.exitCode=1;}}
function act(s,type,extra={}){let r=E.dispatch(s,{type,...extra});assert(r.ok,r.message);return r.state;}
function go(s,which=0){return act(s,'travel',{id:s.route[which].uid});}
function choose(s,id){return act(s,'choose',{id,nonce:s.event.nonce});}
function routeEnd(s){if(s.phase==='result')s=act(s,'continue');return s;}
function noopEvent(s){const c=E.encounter(s).choices.find(c=>c.id==='leave')||E.encounter(s).choices.find(c=>!E.checkChoice(s,c));return choose(s,c.id);}
test('initial state and independent key',()=>{const s=E.create(7);assert.deepEqual([s.fuel,s.hull,s.money,s.debt,E.used(s)],[60,100,120,12000,0]);assert(!E.KEY.includes('v037'));});
test('base leg grows strictly',()=>E.LEG.slice(1).forEach((v,i)=>assert(v>E.LEG[i])));
test('return fuel increases with route distance',()=>{const s=E.create(7);const arr=[];let d=0;E.LEG.forEach(v=>{d+=v;arr.push(E.homeCost(s,d));});assert.deepEqual(arr,[6,10,14,19,25,32,40,49]);});
test('refuel never reduces home cost',()=>{let s=go(act(E.create(9),'depart'));const before=E.homeCost(s);s=choose(s,'safe');assert.equal(E.homeCost(s),before);assert.equal(s.fuel,82);});
test('persist and reload identical routes',()=>{let s=act(E.create(42),'depart');assert.deepEqual(E.restore(JSON.stringify(s)),s);});
test('first action costs exactly once',()=>{let s=go(act(E.create(42),'depart'));const old=s,event=s.event.nonce;s=choose(s,'safe');assert.equal(s.money,90);const r=E.dispatch(s,{type:'choose',id:'safe',nonce:event});assert.equal(r.ok,false);assert.equal(r.state.money,90);assert.equal(old.money,120);});
test('stale revision cannot act',()=>{let s=act(E.create(7),'depart');const r=E.dispatch(s,{type:'travel',id:s.route[0].uid,expected:0});assert(!r.ok);assert.equal(r.state.depth,0);});
test('no route can spend home reserve',()=>{let s=act(E.create(12),'depart');s.fuel=5;assert(s.route.every(x=>!E.quote(s,x).enabled));assert(!E.dispatch(s,{type:'travel',id:s.route[0].uid}).ok);});
test('event fuel cannot consume reserve',()=>{let s=go(act(E.create(5),'depart'),1);s.fuel=E.homeCost(s)+4;assert(E.checkChoice(s,E.encounter(s).choices.find(c=>c.id==='safe')));});
test('full cargo blocks rather than drops loot',()=>{let s=go(act(E.create(5),'depart'),1);for(let i=0;i<3;i++)s.cargo.push({uid:s.nextUid++,name:'测试货',value:10,size:1});assert.equal(E.used(s),4);assert(E.checkChoice(s,E.encounter(s).choices[0]).includes('货舱'));});
test('depart adds one contract slot only',()=>{let s=act(E.create(2),'depart');assert.equal(E.used(s),1);assert(!E.dispatch(s,{type:'depart'}).ok);});
test('early return allowed, not forced loss',()=>{let s=routeEnd(noopEvent(go(act(E.create(22),'depart'))));const f=s.fuel,c=E.homeCost(s);s=act(s,'return');assert.equal(s.fuel,f-c);assert.equal(s.summary.reward,0);assert.equal(s.phase,'summary');assert(!s.cargo.some(x=>x.contract));});
test('contract reward after three safe points, once',()=>{let s=act(E.create(17),'depart');for(let i=0;i<3;i++){s=routeEnd(noopEvent(go(s)));}const cash=s.money;s=act(s,'return');assert.equal(s.money,cash+180);assert(!E.dispatch(s,{type:'return'}).ok);});
test('contract discarded means no fee or reward',()=>{let s=act(E.create(17),'depart');s=act(s,'discard',{id:s.cargo[0].uid});for(let i=0;i<3;i++)s=routeEnd(noopEvent(go(s)));s=act(s,'return');assert.equal(s.summary.reward,0);assert.equal(s.debt,12000);});
test('return does not sell or repay automatically',()=>{let s=routeEnd(choose(go(act(E.create(12),'depart'),1),'force'));const value=E.cargoValue(s);s=act(s,'return');assert.equal(E.cargoValue(s),value);assert.equal(s.debt,12000);});
test('sale can occur once only',()=>{let s=act(routeEnd(choose(go(act(E.create(12),'depart'),1),'force')),'return');const value=E.cargoValue(s),cash=s.money;s=act(s,'sellAll');assert.equal(s.money,cash+value);assert(!E.dispatch(s,{type:'sellAll'}).ok);});
test('sell stale station option rejects missing cargo',()=>{let s=act(E.create(12),'depart');s.cargo.push({uid:s.nextUid++,name:'回收品',value:50,size:1,acquiredRun:1});s=E.restore({...s,schema:2});s=routeEnd(noopEvent(go(s)));s=go(s);const good=s.cargo.find(x=>!x.contract);s=act(s,'discard',{id:good.uid});assert(E.checkChoice(s,E.encounter(s).choices.find(x=>x.id==='sale')));});
test('debt payment leaves supply reserve',()=>{let s=E.create(12);assert(!E.dispatch(s,{type:'repay',amount:100}).ok);s.money=600;s=act(s,'repay',{amount:500});assert.equal(s.money,100);assert.equal(s.debt,11500);});
test('repair and fuel price matches actual amount',()=>{let s=E.create(3);s.fuel=95;s=act(s,'buyFuel');assert.equal(s.money,110);assert.equal(s.fuel,100);assert(!E.dispatch(s,{type:'buyFuel'}).ok);});
test('partial port service does not overfill',()=>{let s=E.create(3);s.hull=94;s=act(s,'repair');assert.equal(s.money,108);assert.equal(s.hull,100);});
test('tool purchase permanent, never duplicate',()=>{let s=E.create(3);s.money=600;s=act(s,'tool',{id:'scanner'});assert(s.tools.includes('scanner'));assert(!E.dispatch(s,{type:'tool',id:'scanner'}).ok);});
test('deterministic seeded danger across restore',()=>{let s=go(act(E.create(3),'depart'));s.event.id='mirror';const a=choose(s,'risk'),b=choose(E.restore(JSON.stringify(s)),'risk');assert.deepEqual(a,b);});
test('hull zero rescues, old debt unchanged',()=>{let s=go(act(E.create(3),'depart'),1);s.hull=10;s=choose(s,'force');assert.equal(s.phase,'summary');assert(s.summary.rescue);assert.equal(s.debt,12000);assert(s.hull>=35&&s.fuel>=18);assert.equal(s.cargo.length,0);});
test('port aid prevents zero-cash soft lock',()=>{let s=E.create(3);s.money=0;s.fuel=0;s.hull=1;s=act(s,'aid');assert(s.fuel>=20&&s.hull>=40);assert.equal(s.money,0);assert(!E.dispatch(s,{type:'aid'}).ok);});
test('corrupt save rejected instead of reset',()=>{assert.throws(()=>E.restore('{oops'));const s=E.create(3);s.fuel=-1;assert.throws(()=>E.restore(s));});
test('start new voyage keeps cash fuel hull',()=>{let s=act(routeEnd(noopEvent(go(act(E.create(2),'depart')))),'return');const [fuel,hull,money]=[s.fuel,s.hull,s.money];s=act(s,'port');s=act(s,'depart');assert.deepEqual([s.fuel,s.hull,s.money],[fuel,hull,money]);assert.equal(s.depth,0);assert.equal(s.distance,0);});
test('capped eight nodes, never infinite mode',()=>{let s=E.create(78);s.money=10000;s=act(s,'depart');s.fuel=100;for(let i=0;i<8;i++){s.fuel=100;s=routeEnd(noopEvent(go(s)));}assert.equal(s.depth,8);assert.equal(s.route.length,0);});
test('engine never advances because wall-clock passed',()=>{let s=act(E.create(4),'depart'),t=E.restore(JSON.stringify(s));assert.deepEqual(t,s);});
test('even detours never make the next leg cheaper',()=>{let s=act(E.create(71),'depart');for(let i=0;i<5;i++){s.fuel=100;s=go(s,1);const last=s.lastLeg;s=routeEnd(noopEvent(s));for(const r of s.route)assert(r.fuel>last);}});
// Deterministic safety simulations, not human play, retention or optimal-strategy evidence.
let sim={runs:0,actions:0,rescues:0,depths:{},policies:{}};
function simulate(seed,policy){let s=act(E.create(seed),'depart'),actions=0;while(s.phase!=='summary'&&actions++<60){if(s.phase==='route'){let valid=s.route.filter(r=>E.quote(s,r).enabled);if(s.depth>=8||!valid.length||(policy==='cautious'&&s.depth>=3)||(s.hull<26)||(policy==='cautious'&&E.used(s)===s.capacity&&s.depth>=3)){s=act(s,s.depth?'return':'abort');if(s.phase==='port')break;continue;}let r=valid[policy==='deep'?valid.length-1:0];s=act(s,'travel',{id:r.uid});}else if(s.phase==='event'){let choices=E.encounter(s).choices.filter(c=>!E.checkChoice(s,c));let score=c=>{let e=c.effect;return(e.fuel||0)*2+(e.bonusFuel||0)*2+(e.money||0)+(e.loot||[]).reduce((n,x)=>n+x.value,0)*.7+(e.hull||0)*(policy==='deep'?1.1:3.5)-(c.risk?(policy==='deep'?15:45):0);};choices.sort((a,b)=>score(b)-score(a));s=choose(s,choices[0].id);}else if(s.phase==='result')s=act(s,'continue');E.assertState(s);if(['route','event','result'].includes(s.phase))assert(s.fuel>=E.homeCost(s));}assert(actions<60);if(s.phase==='summary'){sim.rescues+=Number(s.summary.rescue);const d=s.depth;sim.depths[d]=(sim.depths[d]||0)+1;const p=sim.policies[policy]||(sim.policies[policy]={runs:0,depth:0,cashChange:0,unsoldValue:0});p.runs++;p.depth+=d;p.cashChange+=s.money-120;p.unsoldValue+=E.cargoValue(s);}sim.runs++;sim.actions+=actions;}
test('600 deterministic runs: ledgers, reserve and no deadlock',()=>{for(let seed=1;seed<=300;seed++){simulate(seed,'cautious');simulate(seed,'deep');}});
for(const p of Object.values(sim.policies)){p.avgDepth=+(p.depth/p.runs).toFixed(2);p.avgActualCashChange=+(p.cashChange/p.runs).toFixed(2);p.avgUnsoldValue=+(p.unsoldValue/p.runs).toFixed(2);}
const fs=require('fs'),path=require('path');fs.mkdirSync(path.join(__dirname,'../verification'),{recursive:true});fs.writeFileSync(path.join(__dirname,'../verification/engine-results.json'),JSON.stringify({testsPassed:passed,...sim,scope:'Node pure rules; scripted policies, not human play or retention.'},null,2));console.log(JSON.stringify({passed,sim},null,2));if(process.exitCode)process.exit(process.exitCode);
